import {textbook} from './curriculum.js?v=3';
import {segments} from './segments.js?v=4';
import {trainingExamples} from './training-examples.js?v=2';
import {available, analysesForWord, filterByObservations, possibilities, grammaticalTuples, answerIsValid, fold, FIELDS_BY_KIND, formTypes, kindOf, distinct, inferFormChoice, checkStructure, structurallySound, filterByPieces, verifyObservation, isWrong, segmentsFor} from './parser.js?v=6';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const {analyses:paradigms,vocabulary}=textbook;
const unitControl=$('#unit');unitControl.replaceChildren(...textbook.units.map(u=>{const o=document.createElement('option');o.value=String(u.id);o.textContent=u.label;return o}));$('#book-title').textContent=textbook.title;$('#book-subtitle').textContent=textbook.subtitle;
let form, start=null,end=null, observations=[], answered=false, step=0, timer=null, formChoice='', choiceSource='';
const currentKind=()=>formChoice==='Imperative'?'Finite':formChoice;
function appendMixedText(container,text){for(const piece of text.split(/([\p{Script=Greek}\p{M}]+)/u)){if(!piece)continue;if(/^[\p{Script=Greek}\p{M}]+$/u.test(piece)){const span=document.createElement('span');span.lang='el';span.className='greek-inline';span.textContent=piece;container.append(span)}else container.append(document.createTextNode(piece))}}

const answerFields=()=>['lemma',...(FIELDS_BY_KIND[currentKind()]||[])];
let answer={};
function setSidebar(open){const sidebar=$('#sidebar'),toggle=$('#sidebar-toggle');document.body.classList.toggle('sidebar-collapsed',!open);toggle.setAttribute('aria-expanded',String(open));toggle.setAttribute('aria-label',open?'Close sidebar':'Open sidebar');for(const child of sidebar.children){if(child.classList.contains('brand')){const text=child.querySelector('.brand-text');text.inert=!open;text.setAttribute('aria-hidden',String(!open));continue}child.inert=!open;child.setAttribute('aria-hidden',String(!open))}}
$('#sidebar-toggle').addEventListener('click',()=>setSidebar(document.body.classList.contains('sidebar-collapsed')));
document.addEventListener('click',e=>{if(!document.body.classList.contains('sidebar-collapsed')&&!e.composedPath().includes($('#sidebar')))setSidebar(false)});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!document.body.classList.contains('sidebar-collapsed')){setSidebar(false);$('#sidebar-toggle').focus()}});
setSidebar(false);
function setView(view){$('.settings').hidden=view!=='practice';$('#practice').hidden=view!=='practice';$('#training').hidden=view!=='training';$$('.nav').forEach(n=>n.classList.toggle('active',n.dataset.view===view));if(view==='training')renderTraining();else stopPlay()}
function letters(s){return Array.from(new Intl.Segmenter('el',{granularity:'grapheme'}).segment(s),x=>x.segment)}
function drawWord(){const l=letters(form.word);$('#word').innerHTML='';l.forEach((v,i)=>{let b=document.createElement('span');const selected=start!==null&&i>=Math.min(start,end??start)&&i<=Math.max(start,end??start);b.className='letter'+(selected?' chosen':'')+(selected&&i===Math.min(start,end??start)?' selection-start':'')+(selected&&i===Math.max(start,end??start)?' selection-end':'');b.textContent=v;b.setAttribute('role','button');b.tabIndex=0;b.setAttribute('aria-label','Select '+v);b.onclick=()=>selectLetter(i);b.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();selectLetter(i)}};$('#word').append(b)});$('#selected').textContent=start===null?'No piece selected':selectedText()}
function selectLetter(i){if(start===null||end!==null){start=i;end=null}else end=i;drawWord()}
function selectedText(){return letters(form.word).slice(Math.min(start,end??start),Math.max(start,end??start)+1).join('')}
function clear(){start=null;end=null;drawWord()}
// Structural problems come from where pieces were selected. Conflicting clues
// are set aside rather than used to narrow; Hard mode shows them after submitting.
const wordLength=()=>letters(form.word).length;
const structureProblems=()=>checkStructure(observations,wordLength());
// Each label is also checked against the word pieces of the displayed form.
// Easy mode shows that verdict at once; otherwise it appears after submitting.
// Until it is shown, a label is only a hypothesis and still narrows.
const verdicts=()=>{const analyses=analysesForWord(paradigms,form.word,+$('#unit').value);return observations.map(o=>verifyObservation(o,analyses,segments))};
const verdictsShown=()=>answered||$('#difficulty').value==='Easy';
const soundObservations=()=>{const sound=structurallySound(observations,wordLength());if(!verdictsShown())return sound;const judged=verdicts();return sound.filter(o=>!isWrong(judged[observations.indexOf(o)]))};
const feedbackHidden=()=>$('#difficulty').value==='Hard'&&!answered;
function currentVerb(){return vocabulary.find(v=>v.lemma===form.lemma)||{lemma:form.lemma,gloss:''}}
function newForm(){const unit=+$('#unit').value;const choices=available(paradigms,unit);if(!choices.length){$('#result').textContent='No verified forms are available for this unit.';return}let options=choices.filter(f=>!form||f.word!==form.word);if(!options.length)options=choices;form=options[Math.floor(Math.random()*options.length)];observations=[];answered=false;start=end=null;formChoice='';choiceSource='';answer={lemma:'',person:'',number:'',case:'',gender:'',tense:'',voice:'',mood:''};$('#lemma-search').value='';$('#selected-verb').textContent='';$('#verb-results').hidden=true;$('#lemma-search').setAttribute('aria-expanded','false');renderFormChoice();renderAnswerButtons();$('#result').innerHTML='';delete $('#result').dataset.status;$('#explorePanel').hidden=true;render()}
function render(){drawWord();renderRecognition();let list=$('#observations');list.innerHTML='';if(!observations.length){list.className='empty';list.textContent='Your clues will appear here as you find them.'}else{list.className='';const problems=feedbackHidden()?[]:structureProblems(),judged=verdictsShown()?verdicts():[];observations.forEach((o,i)=>{let item=document.createElement('div');const mine=problems.filter(p=>p.indexes.includes(i)).map(p=>p.message),verdict=judged[i];if(verdict&&isWrong(verdict))mine.push(verdict.message);const confirmed=!mine.length&&verdict&&verdict.status==='correct';item.className='ob'+(mine.length?' conflict':confirmed?' confirmed':'');let txt=document.createElement('span');let b=document.createElement('b');b.textContent=o.text;txt.append(b,document.createTextNode(o.category));let del=document.createElement('button');del.className='textbtn';del.textContent='Remove';del.onclick=()=>{observations.splice(i,1);reconcileInferredType();render()};if(confirmed){const ok=document.createElement('span');ok.className='ob-check';ok.textContent='✓';ok.setAttribute('role','img');ok.setAttribute('aria-label','Fits this form');txt.append(ok)}item.append(txt,del);for(const message of mine){const note=document.createElement('p');note.className='ob-problem';appendMixedText(note,message);item.append(note)}if(!mine.length&&verdict&&verdict.status==='unchecked'){const note=document.createElement('p');note.className='ob-note';note.textContent=verdict.message;item.append(note)}list.append(item)})}renderPossibilities();$('#showExplore').disabled=$('#explore').value==='Hidden'||($('#explore').value==='After answering'&&!answered);$('#showExplore').style.opacity=$('#showExplore').disabled?'.45':'1'}
function updateEvidenceMeter(level,status){const meter=$('#evidence-meter');meter.setAttribute('aria-label',status+'. Based on observations, not correctness.');meter.querySelector('.meter-text').textContent=status;[...meter.querySelectorAll('i')].forEach((bar,i)=>bar.classList.toggle('filled',i<level))}
function renderPossibilities(){
 const box=$('#possibilities');box.replaceChildren();
 if($('#difficulty').value==='Hard'&&!answered){updateEvidenceMeter(0,'Hidden in Hard mode');$('#feedback').textContent='Feedback appears after you submit.';return}
 const kind=currentKind(),all=available(paradigms,+$('#unit').value,kind||undefined),pool=formChoice==='Imperative'?all.filter(a=>a.mood==='Imperative'):kind==='Finite'?all.filter(a=>a.mood!=='Imperative'):all,sound=soundObservations(),conflict=sound.length<observations.length,candidates=filterByPieces(pool,sound,segments);
 const assuming=conflict?'Clues that need another look are set aside. Assuming the rest are correct:':'Assuming your observations are correct:';
 if(!kind){const types=formTypes(candidates);const level=!sound.length||!candidates.length?0:types.length===1?2:1;updateEvidenceMeter(level,!candidates.length?'No known matches':conflict?'Some clues need another look':!observations.length?'No clues':'Not enough');$('#feedback').textContent=observations.length?assuming:'Select and label parts of the word to narrow the possibilities.';const row=document.createElement('div');row.className='poss';const h=document.createElement('strong');h.textContent='Form type';const value=document.createElement('span');value.textContent=types.length?types.join(' · '):'No known matches';row.append(h,value);box.append(row);const note=document.createElement('p');note.className='poss-reason';note.textContent='Choose or identify a form type to see its grammatical features.';box.append(note);return}
 const values=possibilities(candidates,kind);
 const tuples=grammaticalTuples(candidates,kind);
 // Full bars mean one grammatical tuple remains among the available paradigms.
 const proven=sound.length>0&&!conflict&&tuples.length===1;
 const narrowed=FIELDS_BY_KIND[kind].filter(k=>values[k].length===1).length;
 const proportion=narrowed/FIELDS_BY_KIND[kind].length;
 const level=!candidates.length?0:proven?4:proportion>=.75?3:proportion>=.25?2:1;
 updateEvidenceMeter(level,!candidates.length?'No known matches':conflict?'Some clues need another look':proven?'One grammatical analysis remains in the available paradigms':level===3?'Mostly there':'Not enough');
 $('#feedback').textContent=observations.length?assuming:'Select and label parts of the word to see how they narrow the possibilities.';
 const reasons={person:[],number:[],case:[],gender:[],tense:[],voice:[],mood:[]};
 for(const o of sound){
  if(o.category==='Augment'){reasons.tense.push('An augment indicates a past indicative; imperfect, aorist, and pluperfect remain possible until other clues narrow them.');reasons.mood.push('A past-tense augment points to the indicative.')}
  if(o.category==='Present stem')reasons.tense.push('A present stem can form the present or the imperfect.');
  if(o.category==='Future stem')reasons.tense.push('A future stem points to the future system.');
  if(o.category==='Aorist stem')reasons.tense.push('An aorist stem points to the aorist system.');
  if(o.category==='Perfect stem')reasons.tense.push('A perfect stem can appear in the perfect and pluperfect.');
  if(o.category==='Personal ending'){if(fold(o.text)==='μεν')reasons.person.push('The ending -μεν indicates first person plural.');else reasons.person.push(`The ending ${o.text} is compared with the endings in the available paradigms; multiple parses may remain.`)}
  if(o.category==='Thematic vowel')reasons.tense.push(`The vowel ${o.text} is matched against forms that have it between stem and ending.`);
  if(o.category==='Infinitive ending')reasons.voice.push(`The ending ${o.text} is compared with the available infinitive forms.`);
  if(o.category==='Nominal ending')reasons.case.push(`The ending ${o.text} is compared with the available participial forms.`);
  if(o.category==='Reduplication')reasons.tense.push(`Reduplication ${o.text}- is matched against forms that begin their stem that way; perfect reduplication points to the perfect system.`);
  if(o.category==='Tense / mood marker'){if(fold(o.text)==='οι')reasons.mood.push('An identified -οι- optative marker indicates the optative mood.');else reasons.tense.push(`The marker ${o.text} is matched against forms that have that marker.`);}
 }
 const names={person:'Person & number',number:'Number',case:'Case',gender:'Gender',tense:'Tense',voice:'Voice',mood:'Mood'};
 for(const key of FIELDS_BY_KIND[kind]){const title=names[key];
  const row=document.createElement('div');row.className='poss';const heading=document.createElement('strong');heading.textContent=title;const value=document.createElement('span');value.textContent=values[key].length?values[key].join(' · '):'No known possibilities — reconsider the clues.';row.append(heading,value);
  for(const reason of reasons[key]){const explanation=document.createElement('p');explanation.className='poss-reason';appendMixedText(explanation,reason);row.append(explanation)}box.append(row)
 }
 const note=document.createElement('p');note.className='poss-reason';note.textContent='Results cover the available paradigms, not every form of every verb.';box.append(note)
}
function submit(){
 if(!formChoice){$('#result').dataset.status='incorrect';$('#result').textContent='Identify the form before checking the parse.';return}const missing=answerFields().filter(k=>!answer[k]);if(missing.length){$('#result').dataset.status='incorrect';$('#result').textContent='Choose a value for each part of the parse before checking.';return}
 answered=true;const kind=currentKind(),matches=analysesForWord(paradigms,form.word,+$('#unit').value,kind);const correct=answerIsValid(paradigms,form.word,+$('#unit').value,answer,kind);
 $('#result').replaceChildren();const title=document.createElement('strong');title.textContent=correct?'That’s right!':matches.length?'Not quite — review the possible parses below.':'No known analysis matches that form type. Try a different identification.';$('#result').append(title);
 const shownCuts=new Set();
 for(const a of matches){const detail=document.createElement('div');const text=kind==='Finite'?`${a.lemma} · ${a.person} · ${a.tense} ${a.voice.toLowerCase()} ${a.mood.toLowerCase()}`:kind==='Infinitive'?`${a.lemma} · ${a.tense} ${a.voice.toLowerCase()} infinitive`:`${a.lemma} · ${a.tense} ${a.voice.toLowerCase()} participle · ${a.case.toLowerCase()} ${a.number.toLowerCase()} ${a.gender.toLowerCase()}`;appendMixedText(detail,text);$('#result').append(detail);
  // Word pieces of this analysis, shown once per distinct cut.
  const pieces=segmentsFor(a,segments),cut=pieces&&pieces.map(p=>`${p[0]} ${p[1].toLowerCase()}`).join(' · ');if(cut&&!shownCuts.has(cut)){shownCuts.add(cut);const line=document.createElement('div');line.className='pieces';appendMixedText(line,cut);$('#result').append(line)}}
 render();
}
function explore(){const panel=$('#explorePanel');panel.hidden=!panel.hidden;if(!panel.hidden)panel.textContent='Explore forms will be available in a later version.'}
const trainingSelect=$('#training-example');
for(const group of [...new Set(trainingExamples.map(example=>example.group))]){const optgroup=document.createElement('optgroup');optgroup.label=group;trainingExamples.forEach((example,index)=>{if(example.group!==group)return;const option=document.createElement('option');option.value=String(index);option.textContent=`${example.word} — ${example.title}`;optgroup.append(option)});trainingSelect.append(optgroup)}
let training=trainingExamples[0].pieces;
function renderTraining(){const example=trainingExamples[+trainingSelect.value];training=example.pieces;$('#training-title').textContent=example.title;$('#training-parse').replaceChildren();appendMixedText($('#training-parse'),example.parse);$('#trainingWord').classList.remove('paused');let s=training[step];$('#trainingWord').innerHTML='';training.forEach((p,i)=>{let el=document.createElement('span');el.textContent=p[0];el.className='training-piece'+(i===step?' on':'');el.style.setProperty('--offset',`${(i-(training.length-1)/2)*14}px`);$('#trainingWord').append(el)});$('#stepCount').textContent=`PIECE ${step+1} OF ${training.length}`;$('#stepTitle').textContent=s[1];$('#stepText').replaceChildren();appendMixedText($('#stepText'),s[2]);$('#previous').disabled=step===0;$('#next').textContent=step===training.length-1?'Try it yourself →':'Next piece →'}
trainingSelect.addEventListener('change',()=>{stopPlay();step=0;renderTraining()});
function stopPlay(){clearInterval(timer);timer=null;$('#trainingWord').classList.add('paused');$('#play').textContent='▶ Play animation'}
const recognitionGroups=[
  {name:'Beginning',labels:['Augment','Reduplication']},
  {name:'Stem',labels:['Present stem','Future stem','Aorist stem','Perfect stem']},
  {name:'Marker',labels:['Tense / mood marker']},
  {name:'Vowel',labels:['Thematic vowel']},
  {name:'Ending',labels:['Personal ending','Infinitive ending','Nominal ending']}
];
function renderRecognition(){const root=$('.recognition-buttons');root.replaceChildren();for(const group of recognitionGroups){const stack=document.createElement('div');stack.className='recognition-stack';stack.setAttribute('role','group');stack.setAttribute('aria-label',group.name);for(const label of group.labels){const button=document.createElement('button');button.type='button';button.className='recognition-option';button.textContent=label;button.setAttribute('aria-pressed',String(observations.some(o=>o.category===label)));button.onclick=()=>addObservation(label,group);stack.append(button)}root.append(stack)}}
function addObservation(category,group){if(start===null){$('#selected').textContent='Select letters in the word first.';return}const o={text:selectedText(),category,start:Math.min(start,end??start),end:Math.max(start,end??start)};observations=observations.filter(previous=>!group.labels.includes(previous.category));observations.push(o);clear();reconcileInferredType();render();if($('#difficulty').value==='Easy'&&!structureProblems().length&&!verdicts().some(isWrong)&&currentKind()&&!filterByPieces(analysesForWord(paradigms,form.word,+$('#unit').value,currentKind()),observations,segments).length)$('#feedback').textContent='These clues do not fit a known analysis of this form.'}
document.addEventListener('click',e=>{if(start!==null&&!e.composedPath().includes($('#word'))&&!e.composedPath().includes($('#recognition')))clear()});
$('#clear').onclick=clear;$('#new').onclick=newForm;$('#unit').onchange=()=>{newForm()};$('#difficulty').onchange=()=>{save();reconcileInferredType();render()};$('#explore').onchange=()=>{save();$('#explorePanel').hidden=true;render()};$('#submit').onclick=submit;$('#showExplore').onclick=explore;$$('.nav').forEach(n=>n.onclick=()=>setView(n.dataset.view));$('#skip').onclick=()=>setView('practice');$('#previous').onclick=()=>{stopPlay();step=Math.max(0,step-1);renderTraining()};$('#next').onclick=()=>{stopPlay();if(step===training.length-1){setView('practice');return}step++;renderTraining()};$('#play').onclick=()=>{if(timer){stopPlay();return}if(step===training.length-1)step=0;renderTraining();$('#play').textContent='Ⅱ Pause animation';timer=setInterval(()=>{if(step===training.length-1){stopPlay();return}step++;renderTraining()},6500)};
function save(){try{localStorage.setItem('roots-settings',JSON.stringify({unit:$('#unit').value,difficulty:$('#difficulty').value,explore:$('#explore').value}))}catch{}}
const betaMap={α:'a',β:'b',γ:'g',δ:'d',ε:'e',ζ:'z',η:'h',θ:'q',ι:'i',κ:'k',λ:'l',μ:'m',ν:'n',ξ:'c',ο:'o',π:'p',ρ:'r',σ:'s',ς:'s',τ:'t',υ:'u',φ:'f',χ:'x',ψ:'y',ω:'w'};
function betaCode(word){return [...word.normalize('NFD').toLowerCase()].filter(c=>!/[\u0300-\u036f]/.test(c)).map(c=>betaMap[c]??c).join('')}
const finiteGroups=[['person','Person / number',['1st singular','1st plural','2nd singular','2nd plural','3rd singular','3rd plural']],['tense','Tense',['Present','Imperfect','Future','Aorist','Perfect','Pluperfect']],['voice','Voice',['Active','Middle','Passive']],['mood','Mood',['Indicative','Subjunctive','Optative','Imperative']]];
const infinitiveGroups=[['tense','Tense',['Present','Future','Aorist','Perfect']],['voice','Voice',['Active','Middle','Passive']]];
const participleGroups=[['tense','Tense',['Present','Future','Aorist','Perfect']],['voice','Voice',['Active','Middle','Passive']],['case','Case',['Nominative','Genitive','Dative','Accusative','Vocative']],['number','Number',['Singular','Plural']],['gender','Gender',['Masculine','Feminine','Neuter']]];
const imperativeGroups=[['tense','Tense',['Present','Aorist','Perfect']],['voice','Voice',['Active','Middle','Passive']],['person','Person / number',['2nd singular','2nd plural','3rd singular','3rd plural']]];
function renderAnswerButtons(){const root=$('#parse-groups'),kind=currentKind();$('#choose-form-note').hidden=!!kind;if(!kind){root.replaceChildren();return}const groups=formChoice==='Imperative'?imperativeGroups:kind==='Finite'?finiteGroups:kind==='Infinitive'?infinitiveGroups:participleGroups;root.replaceChildren();root.classList.toggle('participle-layout',kind==='Participle');root.style.gridTemplateColumns=formChoice==='Finite'?'1.35fr 1fr .9fr 1fr':kind==='Participle'?'1fr 1fr 0px 1fr 1fr 1fr':`repeat(${groups.length}, minmax(0,1fr))`;for(const [key,title,options] of groups){const field=document.createElement('fieldset');field.className='parse-group'+(key==='person'?' person-group':'');const legend=document.createElement('legend');legend.textContent=title;field.append(legend);const buttons=document.createElement('div');buttons.className='parse-options';for(const option of options){if(formChoice==='Finite'&&key==='mood'&&option==='Imperative')continue;const button=document.createElement('button');button.type='button';button.className='parse-option';button.textContent=key==='person'?option.replace('st singular','SG.').replace('nd singular','SG.').replace('rd singular','SG.').replace('st plural','PL.').replace('nd plural','PL.').replace('rd plural','PL.'):option;if(key==='person')button.setAttribute('aria-label',option);button.setAttribute('aria-pressed',String(answer[key]===option));button.onclick=()=>{answer[key]=option;renderAnswerButtons()};buttons.append(button)}field.append(buttons);root.append(field)}}
function setFormChoice(choice,source){if(formChoice!==choice){formChoice=choice;answer={lemma:answer.lemma||'',person:'',number:'',case:'',gender:'',tense:'',voice:'',mood:choice==='Imperative'?'Imperative':''};answered=false;$('#result').textContent='';delete $('#result').dataset.status}choiceSource=source;renderFormChoice();renderAnswerButtons()}
function reconcileInferredType(){if(choiceSource==='manual')return;const next=$('#difficulty').value==='Hard'&&!answered?'':inferFormChoice(soundObservations(),paradigms,+$('#unit').value);if(next!==formChoice)setFormChoice(next,next?'inferred':'')}
function renderFormChoice(){const root=$('#form-choice');root.replaceChildren();for(const choice of ['Finite','Infinitive','Imperative','Participle']){const button=document.createElement('button');button.type='button';button.className='recognition-option';button.textContent=choice==='Finite'?'Finite (other)':choice;const pool=available(paradigms,+$('#unit').value,choice==='Imperative'?'Finite':choice);button.disabled=choice==='Imperative'?!pool.some(a=>a.mood==='Imperative'):choice==='Finite'?!pool.some(a=>a.mood!=='Imperative'):!pool.length;button.setAttribute('aria-pressed',String(choice===formChoice));button.onclick=()=>{setFormChoice(choice,'manual');render()};root.append(button)}}
function showVerbResults(){const input=$('#lemma-search');let query=input.value.toLowerCase().trim();if(input.value!==query)input.value=query;answer.lemma='';$('#selected-verb').textContent='';const results=$('#verb-results');results.replaceChildren();const matches=query?vocabulary.filter(v=>v.unit<=+$('#unit').value&&betaCode(v.lemma).startsWith(query)):[];results.hidden=!query;input.setAttribute('aria-expanded',String(!!query));if(!query)return;if(!matches.length){const empty=document.createElement('div');empty.className='no-results';empty.textContent='No matching verbs through this unit.';results.append(empty);return}for(const verb of matches){const button=document.createElement('button');button.type='button';button.className='verb-result';const greek=document.createElement('strong');greek.textContent=verb.lemma;const gloss=document.createElement('span');gloss.textContent=verb.gloss;button.append(greek,gloss);button.onclick=()=>{answer.lemma=verb.lemma;input.value=verb.lemma;$('#selected-verb').textContent=verb.gloss;results.hidden=true;input.setAttribute('aria-expanded','false')};results.append(button)}}
$('#lemma-search').addEventListener('input',showVerbResults);
$('#lemma-search').addEventListener('focus',e=>{if(answer.lemma&&e.currentTarget.value===answer.lemma)e.currentTarget.select()});
$('#lemma-search').addEventListener('keydown',e=>{if(e.key==='Escape'){$('#verb-results').hidden=true;e.currentTarget.setAttribute('aria-expanded','false')}if(e.key==='ArrowDown'&&!$('#verb-results').hidden){const first=$('#verb-results button');if(first){e.preventDefault();first.focus()}}});
try{const saved=JSON.parse(localStorage.getItem('roots-settings')||'{}');for(const k of ['unit','difficulty','explore'])if(saved[k])$('#'+k).value=saved[k]}catch{}$('#unit').addEventListener('change',save);newForm();
